import torch

class DiffTwoTensor(torch.Tensor):
    def __new__(
        cls,
        data: torch.Tensor,
    ):
        self = torch.Tensor._make_wrapper_subclass(
            cls,
            data.size(),
            strides=data.stride(),
            storage_offset=data.storage_offset(),
            dtype=data.dtype,
            layout=data.layout,
            requires_grad=data.requires_grad,
            device=data.device,
        )
        self._data = data
        return self

    def __tensor_flatten__(self):
        ctx = {}
        return ["_data"], ctx

    @staticmethod
    def __tensor_unflatten__(inner_tensors, metadata):
        return DiffTwoTensor(inner_tensors["_data"])

    @classmethod
    def __torch_dispatch__(cls, func, types, args, kwargs=None):
        diff_two_tensor = args[0]
        out = func(diff_two_tensor._data, *args[1:], **kwargs)
        return DiffTwoTensor(out, diff_two_tensor._scale)

    def __repr__(self):
        return f"{self._data.__repr__()}"

@torch.compile(backend="aot_eager")
def f(x):
    y = DiffTwoTensor(x)
    z = torch.ops.aten.sin(y._data)
    return z

x = torch.randn(3)
y = f(x)
assert torch.allclose(y, x.sin())
